"New stripes suit you!":"नई पट्टियाँ तुम पर जँचती हैं!",
"Pod inbound! Reinforcements!":"पॉड आ रहा है! मदद आ रही है!",
"Anyone remember why the sky is a portal?":"किसी को याद है आसमान पोर्टल क्यों है?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"कहते हैं शाफ़्ट में कूदो तो दुश्मन के यहाँ निकलते हो। मैं आज़माऊँगा नहीं।",
"The Swarm painted their visors red again. Show-offs.":"झुंड ने फिर विज़र लाल रंग दिए। दिखावेबाज़।",
"Ore, ore… when do we get some oil?":"अयस्क, अयस्क… चिकनाई कब मिलेगी?",
"I dreamt I was a toaster. It was peaceful.":"मैंने सपना देखा कि मैं टोस्टर हूँ। सुकून था।",
"Quiet. Too quiet.":"शांति है। बहुत ज़्यादा शांति।",
"See that? Our base is above the Swarm base again. Portals, man.":"देखा? झुंड के अड्डे के ऊपर फिर हमारा अड्डा है। पोर्टल, भई।",
"Diman, if you're reading this — we need a vacation.":"दिमान, अगर तुम यह पढ़ रहे हो — हमें छुट्टी चाहिए।",
