"Autosaved":"ऑटोसेव हुआ",
"robot war · the sky is a portal":"रोबोट युद्ध · आसमान एक पोर्टल है",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"उल्कापिंड पर स्वागत है! तुम कंसोर्टियम के लड़ाकू रोबोट हो। माउस से चारों ओर देखो और WASD से चलो।",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"जेटपैक: Shift दबाओ — कूद, Shift थामो — उड़ान। ऊर्जा ज़मीन पर भरती है।",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"फ़ायर — बायाँ क्लिक। निशाना — दायाँ क्लिक: ज़्यादा सटीक, ज़ूम के साथ। कुछ गोलियाँ चलाओ।",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"रीलोड — R। गोलियाँ मध्यम दूरी, 20–50 मीटर पर सबसे तेज़ लगती हैं।",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"रॉकेट — Q। टैंकों और इमारतों के लिए। एक रॉकेट छोड़ो।",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"ऊपर रणनीतिकार का आदेश है। हरे तीरों के साथ दौड़ो: रास्ते पर तुम स्प्रिंट करते हो। बिंदु पर क़ब्ज़ा करो — बीकन के पास खड़े रहो।",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"तुम्हारा दस्ता तुम्हें कवर दे रहा है: उनकी तस्वीरें और सेहत बाईं ओर हैं। पीछे रह गए तो वे रुकने को कहेंगे।",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — लड़ाई छोड़े बिना तेज़ यूनिट बदलना: लड़ाई के सबसे पास के दस्ते या टैंक में कूदो। आज़माओ।",
"Next to a tank or turret press E to take control. Or just carry on.":"टैंक या बुर्ज के पास E दबाकर उसे चलाओ। या बस आगे बढ़ते रहो।",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"अब रणनीति। ऊपर दाएँ \"◩ रणनीति\" पर टैप करो — युद्धक्षेत्र का ऊपरी दृश्य।",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"अब रणनीति। {0} दबाओ (या ऊपर बाएँ \"◩ रणनीति\") — युद्धक्षेत्र का ऊपरी दृश्य।",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"रणनीति में क्यूरेटर तुम्हारी मदद करता है: ऊपर का बॉक्स बताता है क्या करना है, फ़्रेम बटन दिखाता है, घेरा नक्शे पर जगह बताता है। उसकी तीन सलाहें पूरी करो।",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"कोई दस्ता चुनो और हरा \"▶ नियंत्रण लो\" बटन दबाओ — उसी सैनिक के रूप में फिर लड़ाई में। जब तुम गोली चलाते हो, AI रणनीतिकार सेना संभालता है।",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"कोई दस्ता चुनो और {0} या हरा \"▶ नियंत्रण लो\" दबाओ — उसी सैनिक के रूप में फिर लड़ाई में (कुछ न चुना हो तो अपने में)। जब तुम गोली चलाते हो, AI रणनीतिकार सेना संभालता है।",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"प्रशिक्षण पूरा! हिवे का हमला शुरू हो रहा है। शुभकामनाएँ, सैनिक!",
