"Powers":"शक्तियाँ",
"RMB on a button — cancel the last order":"बटन पर दायाँ क्लिक — आख़िरी ऑर्डर रद्द करो",
"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"निर्माण सिर्फ़ इंजीनियर करते हैं। इंजीनियर न चुना हो तो बटन सबसे पास का खाली इंजीनियर चुनकर नक्शा चालू कर देगा; फिर जगह पर बायाँ क्लिक।",
"Pick a power, then click the target":"शक्ति चुनो, फिर लक्ष्य पर क्लिक करो",
"Controls":"नियंत्रण",
"All strategy keys":"रणनीति की सभी कुंजियाँ",
"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"चालू — खुद बेस बनाता है, सैनिक मँगवाता है और आदेश देता है (तुम्हारे आदेश को प्राथमिकता)। बंद — सब कुछ तुम खुद करते हो।",
"Auto-build on: the strategist builds the base with builders":"ऑटो-निर्माण चालू: रणनीतिकार इंजीनियरों से बेस बनाता है",
