"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"अयस्क का नया रूप: अयस्क शिराएँ काले बेसाल्ट पर चमकते पन्ना-हरे तराशे क्रिस्टल हैं, चिंगारियों और हरी धुंध के साथ; एक्सट्रैक्टर षट्कोणीय चबूतरा है जिस पर छत्तेदार गुंबद और जालीदार मीनार है, ऊपर हरी बत्ती (पट्टी और झंडी — टीम के रंग में)",
"New in v6.1":"v6.1 में नया",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Battlefield की तरह अपना पसंदीदा क्लास (U, मरने के बाद अंक): उपलब्ध होने पर आप उसी में लौटते हैं",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"वाहन पहले व्यक्ति के दृश्य में (V — बाहर/कॉकपिट); हल्का ऑटो-निशाना — सेटिंग्स में",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"कोर से निकलना आसान: Space — शाफ़्ट तक, B — सतह तक कैप्सूल; मरने पर क्षमताओं के प्रभाव रीसेट हो जाते हैं",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"अंतहीन प्रगति: जनरल और मार्शल ★, करियर स्तर, हथियार की महारत और अटैचमेंट, पदक, दैनिक अनुबंध — करियर स्क्रीन",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"रणनीति: स्क्रॉल-व्हील से स्मूद ज़ूम, यूनिट के ऊपर आइकन और लेबल (Alt — सभी), बाईं ओर «सेना / इमारतें» पैनल",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"RMB — रास्ते में लड़ते हुए आगे बढ़ो, डबल RMB — चलते-चलते फ़ायर करते हुए कूच; दुर्लभ आदेश «और आदेश ▾» में; बटन दोहराए नहीं जाते",
"New in v6":"v6 में नया",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"शूटर जैसी गन: तुरंत लगने वाली गोलियाँ, 720 RPM राइफ़ल, MG, रीकॉइल, RMB से निशाना, मैगज़ीन और R से रीलोड, हिट मार्कर",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"भारी गुरुत्वाकर्षण, तेज़ जेटपैक, Z से या हवा में डबल जेट से डैश; दूसरे यूनिट में जाते समय हथियार अब साथ नहीं उड़ता",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"इंजीनियर: इंजीनियर चुनो, इमारत चुनो, ब्लूप्रिंट लगाओ; अयस्क शिराओं पर एक्सट्रैक्टर; आय देखने और बढ़ाने के तरीके के लिए «अयस्क» पर क्लिक करो",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"धूसर बटन दबाने पर कारण और समाधान बटन दिखता है; बड़े बटन, «जारी है» पट्टी, «▶ अधिकार लें», Tab — मोड की एकमात्र कुंजी",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"बिना झटकों और पलटने वाला रणनीति कैमरा, कर्सर की ओर ज़ूम, खींचने योग्य मिनीमैप",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"नए वाहन: रेडर \"Jackal\", रॉकेट तोप \"Grad\" (निशाना खोजने वाले रॉकेट), मोर्टार \"Hammer\"; Swarm को मिले \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"रणनीतिकार आदेश बार-बार नहीं बदलता और आवाज़ से स्पैम नहीं करता; लड़ाइयाँ तुम्हारे पास आती हैं; B — तैनाती बदलो, Shift+B — लड़ाई के बीच; कम्पास, H — कौन-सा लक्ष्य",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"खुली छूट (K) और अकेले खेलना (J), F2 — प्रीसेट; Esc से रोको और फिर चलाओ; सेव: स्लॉट, फ़ाइल एक्सपोर्ट और इम्पोर्ट",
"New in v5.3":"v5.3 में नया",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"उड़ान: उल्कापिंड से दूर गुरुत्व ज़्यादा, हवा में C से ब्रेक, थ्रस्ट तेज़ मुड़ता है; अब आकाश द्वार में अटकते नहीं",
"New in v5":"v5 में नया",
