"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"खुफ़िया: झुंड का दस्ता तुम्हारी ओर आ रहा है — {0}, लगभग {1} मीटर।",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"ऊपर से संपर्क! झुंड का पॉड {0} गिर रहा है, {1} मीटर!",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"झुंड का सिग्नलर {0}! 12 सेकंड में हमला बुलाएगा — पहले उसे मारो!",
