"{0}: on our way to you, commander!":"{0}: हम तुम्हारे पास आ रहे हैं, कमांडर!",
"{0} is with you again.":"{0} फिर तुम्हारे साथ है।",
"Mode: going solo":"मोड: अकेले खेलना",
"Mode: squad with me":"मोड: दस्ता मेरे साथ",
