"Free: orders become quiet suggestions, squad with you":"स्वतंत्र: आदेश चुप सुझाव बनते हैं, दस्ता तुम्हारे साथ",
"Lone wolf: no orders, no squad":"अकेला भेड़िया: न आदेश, न दस्ता",
