"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"कंसोर्टियम का भारी गनर अब कंकाल वाला असली 3D मॉडल है: खड़ा रहता है, चलता है, बंदूक लेकर दौड़ता है, चलते-चलते गोली चलाता है और नष्ट होने पर गिरता है",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"मॉडल उल्कापिंड की सतह के लंबवत खड़ा होता है, निशाने के अनुसार धड़ घुमाता है और मशीन गन हाथों में थामे रहता है; दूर होने पर एनिमेशन कम बार अपडेट होता है ताकि FPS न गिरे",
