"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"पैदल सेना: आक्रमण दस्ते, भारी गनर, स्नाइपर, टोही, ड्रॉप पॉड; कवच और हथियार उन्नयन।",
"Ore depot":"अयस्क डिपो",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"इंजीनियर क्रिस्टल यहाँ जमा करते हैं। इसे क्रिस्टल क्षेत्र के पास लगाओ — आना-जाना कम, अयस्क ज़्यादा।",
"Tanks and vehicles. Requires Barracks.":"टैंक और वाहन। बैरक चाहिए।",
"Autonomous combat drones. Requires Barracks.":"स्वचालित लड़ाकू ड्रोन। बैरक चाहिए।",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"जेटपैक II और आसमानी दस्ता (जेटपैक एलीट)। मेक फ़ैक्टरी चाहिए, 6:00 पर खुलता है।",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"अपने बिंदु पर आगे का अड्डा: इंजीनियर, क्रिस्टल जमा, सैनिक-पूर्ति।",
