"Unlocks in {0}":"{0} में खुलेगा",
"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"जेटपैक और विमान बाद में खुलते हैं — विमान-रोधी रक्षा और बुर्ज लगाने का समय है। तब तक बैरक और मेक फ़ैक्टरी बनाओ।",
"Lone heavy gunner":"अकेला भारी गनर",
"Crystals nearby are depleted — builder is idle":"आसपास के क्रिस्टल खत्म — इंजीनियर खाली है",
"A crystal field is depleted":"क्रिस्टल क्षेत्र खत्म हो गया",
