"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"क्रिस्टल निकालें: इंजीनियर हरे क्षेत्र से माल भरकर मुख्यालय/डिपो तक ले जाता है। या क्रिस्टल पर दायाँ क्लिक करो।",
"Gather":"निकालें",
"crystals":"क्रिस्टल",
