"⚔ Polygon: an endless battle at the map centre with reinforcements. X — possess a soldier there":"⚔ परीक्षण मैदान: नक्शे के केंद्र में अंतहीन लड़ाई, लगातार कुमुक। X — वहाँ किसी सैनिक पर काबू करें",
"Polygon off — its units are back under AI command":"परीक्षण मैदान बंद — उसके सैनिक फिर से AI की कमान में लौट गए",
"polygon":"परीक्षण मैदान",
"Polygon":"परीक्षण मैदान",
