"Voice of hints & curator":"संकेतों और मार्गदर्शक की आवाज़",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"फ़ोन: स्टिक के तीन मोड। सिर्फ़ बायाँ — «ऑटो» (मज़बूत चुंबक, पर गोलियाँ कमज़ोर)। सिर्फ़ दायाँ — निशाना खुद चालू होता है, चुंबक मज़बूत, सटीकता बेहतर। दोनों साथ — निशाना नहीं, चुंबक और सटीकता कम। दाईं ओर 👁 बटन इंटरफ़ेस छिपाता/लौटाता है।",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"फ़ोन: रणनीति सरल की गई — सिर्फ़ इंजीनियर और इमारतें। बाईं ओर कार्ड (इंजीनियर, मुख्यालय, बैरक…): टैप करें — कैमरा वहाँ जाता है, नीचे तुरंत दिखता है क्या बनाना/तैयार करना है। «युद्ध में» — ऊपर बाईं ओर। सेना खुद लड़ती है। पूरी रणनीति — सेटिंग्स → फ़ोन।",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"काबू — दो स्विच: «दस्ते» और «वाहन» (फ़ोन पर वाहन डिफ़ॉल्ट रूप से बंद हैं — उन्हें AI चलाता है)। वाहन बंद हों तो अपने वाहन के पास E (फ़ोन पर — दाईं ओर का बटन) दबाकर उसकी तोप संभालें: वाहन खुद चलता है, आप गोली चलाते हैं। पुराना «वर्गों का अपना क्रम» «उन्नत» में है। काबू करने पर यूनिट रेडियो पर जवाब देती है।",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"स्मार्ट संकेत: बुनियादी संकेत दूसरी बार चलाने के बाद खुद बंद हो जाते हैं, पर जो सुविधा आप कभी इस्तेमाल नहीं करते उसे गेम फिर भी याद दिलाएगा। स्विच: बुनियादी / उन्नत / दुर्लभ, और अलग से — संकेतों और मार्गदर्शक की आवाज़।",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"रिफ़्लेक्स किल से चार्ज होता है (लगातार किल से ज़्यादा)। साथी पीछे रह गए या मारे गए — रणनीतिकार नए सैनिक आपके पास उतारता है (सामान्य कुमक से महँगा)। v7.2gfx के ग्राफ़िक्स और ध्वनि जोड़ दिए गए हैं: घुमड़ते विस्फोट, धुआँ, मलबा, शाफ़्ट और गड्ढों की ध्वनिकी। बिल्ड की तारीख़ अब असली है।",
