"Follow the strategist's orders — XP for them is doubled and tripled.":"रणनीतिकार के आदेश पूरे करो — उनके लिए XP दोगुना और तिगुना मिलता है।",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — लड़ाई के सबसे पास वाले दस्ते या वाहन पर तुरंत जाएँ।",
"Bullets hit hardest at medium range, 20–50 meters.":"गोलियाँ मध्यम दूरी, 20–50 मीटर पर सबसे ज़ोर से लगती हैं।",
"To win, destroy the Swarm HQ and all its key buildings.":"जीतने के लिए स्वार्म का मुख्यालय और उसकी सभी अहम इमारतें गिरा दो।",
