"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"करियर और सेव अपरिवर्तित रहते हैं। मैच में यही मेनू ऊपर दाईं ओर «🛠 मेनू» बटन है{0}।",
"New developer match":"नया डेवलपर मैच",
"all unlocked, endless ore, instant build, arsenal":"सब खुला, अयस्क अनंत, तुरंत निर्माण, शस्त्रागार",
"Trainings — all 4":"प्रशिक्षण — सभी 4",
"PC and phone (strategy and shooter)":"PC और फ़ोन (रणनीति और शूटर)",
"Cinema: split screen":"सिनेमा: स्प्लिट स्क्रीन",
"strategist bot left, shooter bot right":"बाएँ रणनीतिकार बॉट, दाएँ शूटर बॉट",
"Cinema: everything built":"सिनेमा: सब बना",
"both bases built and upgraded — for footage":"दोनों अड्डे बने और अपग्रेड — फ़ुटेज के लिए",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"सिनेमा मोड — स्प्लिट स्क्रीन: बाएँ रणनीतिकार बॉट (अड्डे और सेना का ऊपर से दृश्य), दाएँ शूटर बॉट पहले-व्यक्ति दृश्य में। नीचे बटन (कुंजियाँ S, P): «स्प्लिट स्क्रीन» और «★ सब बना» — फ़ुटेज के लिए दोनों अड्डे बने और अपग्रेड किए हुए।",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"कोर और उल्कापिंड के आर-पार की सुरंगें अब नहीं रहीं — उल्कापिंड ठोस है, लड़ाई सिर्फ़ सतह पर होती है।",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"फ़ोन: 👁 HUD छिपाता है, पर जेटपैक, ⇆, स्टिक और लक्ष्य मार्कर रहने देता है। \"◎ निशाना\" (सिर्फ़ दायाँ अंगूठा) — काफ़ी मज़बूत और चौड़ा मैग्नेट; तीनों मोड के लिए मैग्नेट — सेटिंग्स → नियंत्रण → \"उन्नत\"। वाहन की तोप पर बटन का नाम \"उतरें\" होता है।",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"प्रशिक्षण: फ़ोन पर सिर्फ़ फ़ोन वाले, PC पर सिर्फ़ PC वाले। सभी 4 \"🛠 डेवलपर\" मेनू में हैं। डेवलपर मोड और शस्त्रागार अब एक ही मेनू हैं (लड़ाई में — ऊपर दाएँ \"🛠 मेनू\", PC पर F8)।",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"ग्राफ़िक्स शैलियाँ \"Dendy (8-बिट)\" और \"16-बिट\": सेटिंग्स → ग्राफ़िक्स → \"ग्राफ़िक्स शैली\" (विवरण — ⚙ बटन)। अगर मैच के पहले ~10 s में FPS 24 से नीचे रहे, तो Dendy अपने-आप चालू हो जाती है (20 से भी नीचे — और बड़े पिक्सल, 120 लाइनें); \"सामान्य पर लौटें\" सूचना सामान्य ग्राफ़िक्स हमेशा के लिए बहाल कर देती है। मेनू में तुम्हारा चुनाव हमेशा सर्वोपरि रहता है।",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D परिवेश मॉडल (खंडहर, मलबा, किलेबंदी) — सिर्फ़ अच्छी रेटिंग वाले, माँग पर स्ट्रीम होते हैं। बंद करें: सेटिंग्स → ग्राफ़िक्स → \"नए 3D परिवेश मॉडल\"।",
