"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"सैनिकों से निर्माण: अपने निर्माण स्थल पर E (फ़ोन पर \"प्रवेश\") — तुम्हारा सैनिक खुद बनाता है, पास के साथी मदद करते हैं। अगर इंजीनियर व्यस्त हों, तो रणनीतिकार तुमसे मदद माँगता है — \"निर्माण स्थल\" मार्कर।",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"रणनीतिकार के निशान: रणनीतिकार तुम्हारे पास दुश्मनों के जमावड़े पर ⌖ लगाता है — 8 s बाद वहाँ तोपखाना गिरता है और पास की अपनी MLRS \"Grad\" बौछार करती हैं। रणनीति मोड से तुम्हारा अपना तोपखाना प्रहार भी \"Grad\" की मदद पाता है।",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"मालवाहक कंटेनरों और गिरे उपग्रहों में हथियार भंडार (📦 70 m से दिखता है): E — 90 s के लिए मशीनगन, आग लगाने वाली गोलियाँ या रॉकेट, साथ में पूरे ग्रेनेड। रेंगना: Ctrl — लेटें / खड़े हों (नीचा, शांत, सटीक निशाना, पर धीमा)।",
