"Link copied":"लिंक कॉपी हुआ",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"\"▶ अभी खेलें\" — मेनू का पहला बटन: पोर्टल-आकाश के नीचे छोटी उड़ान — और सीधे लड़ाई में (छोड़ने के लिए कोई भी कुंजी या टैप)।",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"वार असली लगते हैं: धात्विक आवाज़ और चिंगारियाँ, क्रॉसहेयर पर किल मार्कर (हेडशॉट — पीला), ×N शृंखला, धमाकों से सहज हिलना, अहम किल पर स्लो मोशन। हिलना, स्लो मोशन और संकेत सेटिंग्स में बंद किए जा सकते हैं।",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"मैच का नतीजा: समय, नष्ट, सबसे लंबी शृंखला, ★ MVP और सर्वश्रेष्ठ दस्ता, मैच कार्ड — \"⇪ साझा करें\", PNG या खेल का लिंक।",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"संसाधनों के नीचे बाईं ओर \"अभी क्या करें\" संकेत: रणनीतिकार का आदेश, कब्ज़े का बिंदु, झुंड का हमला। ✕ या F7 — समेटें।",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"टैब बंद या छिपाने पर लड़ाई अपने-आप सेव हो जाती है — मेनू में \"⟲ जारी रखें\"।",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 \"🕘 खेल का संस्करण\" मेनू में रहेगा — अगर तुम्हें वही पसंद हो। अब गुमनाम आँकड़े (बिना नाम या ईमेल) भेजे जाते हैं; सेटिंग्स में बंद करें।",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"\"अभी खेलें\", वार का एहसास, साझा कार्ड वाला मैच नतीजा, \"क्या करें\" संकेत, ऑटो-सेव",
"and older: v7.5, v7.4, milestones v1–v7.0":"और पुराने: v7.5, v7.4, पड़ाव v1–v7.0",
"New in v7.6":"v7.6 में नया",
"NEW IN v7.6":"v7.6 में नया",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"मैच से पहले अपना गुट चुनें: \"कंसोर्टियम\" (पावर-आर्मर वाली भारी पैदल सेना, कवच और तोपखाना) या \"झुंड\" (गति, ड्रोन झुंड, विकृति वाले भारी वार)। AI दूसरे गुट से खेलता है। चुनाव याद रखा जाता है।",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"हर गुट के अपने वाहन और खास चीज़ें हैं: कंसोर्टियम के पास टैंक \"गैंडा\" और \"सेरामाइट प्लेटें\", झुंड के पास \"ड्रोन झुंड\" और \"फ़ेज़ जेटपैक\"। संतुलन बॉट मैचों से जाँचा गया है।",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"विस्फोट गड्ढे: तोपखाना, रॉकेट और टैंक की तोपें उल्कापिंड में गड्ढे खोदती हैं — इनमें चल सकते हो, गाड़ी चला सकते हो और इनके अंदर आड़ ले सकते हो।",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"सैनिक के लिए तीसरे व्यक्ति का दृश्य (V, याद रखा जाता है; फ़ोन पर — नियंत्रण) और वाहन का सहज कैमरा, जिसमें निशान दिखाता है कि तोप का गोला कहाँ गिरेगा।",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"अगर नया पसंद न आए, तो v7.6 \"🕘 गेम संस्करण\" मेनू में मौजूद है।",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"कंसोर्टियम / झुंड गुट, मैच से पहले चुनाव, विस्फोट गड्ढे, तीसरे व्यक्ति का दृश्य",
"and older: v7.6, v7.5, milestones v1–v7.0":"और पुराने: v7.6, v7.5, पड़ाव v1–v7.0",
