"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"उंगली ज़मीन पर ~0.3 सेकंड दबाए रखो — फ़ोन काँपेगा और पीला घेरा दिखेगा — फिर उठाए बिना खींचो: फ़्रेम बनेगा। या दाईं ओर \"फ़्रेम\" बटन दबाओ। दस्ते पर बस टैप भी चलता है।",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhone पर पूरी स्क्रीन के लिए: \"शेयर करें\" ⬆ → \"होम स्क्रीन में जोड़ें\" — गेम Safari की पट्टियों के बिना खुलेगा।",
"Open portal-meteor.pages.dev for that.":"इसके लिए portal-meteor.pages.dev खोलो।",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"टैप — चुनें · ज़मीन पर टैप — चलो · दबाए रखो — आदेश मेनू · दबाकर खींचो — फ़्रेम · 2 उंगलियाँ — ज़ूम",
"Robo-ninja":"रोबो-निंजा",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"हत्यारी हीरो: ब्लिंक-डैश, कटाना, शुरिकेन। दुश्मन के इलाकों में खुद टेलीपोर्ट करती है और रोबोट काट डालती है। हर पक्ष की 1।",
"Shadow protocol":"\"शैडो\" प्रोटोकॉल",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"शोध: बैरक में रोबो-निंजा खोलता है। तैयार मेक फ़ैक्टरी चाहिए।",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"हीरो (हर पक्ष की 1): दुश्मन के इलाकों में खुद टेलीपोर्ट करती है और रोबोट काट डालती है; हाथ से खेलने के लिए उस पर \"हावी\" हों",
"is ready. She works on her own (AUTO) — possess her to play manually":"तैयार है। खुद काम करती है (ऑटो) — हाथ से खेलने के लिए हावी हों",
"Robo-ninja ready for action":"रोबो-निंजा लड़ाई के लिए तैयार",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ टोही: दुश्मन के पास रोबो-निंजा आ गई है!",
"Warning! The enemy has a robo-ninja. Stay together":"चेतावनी! दुश्मन के पास रोबो-निंजा है। साथ रहो",
