"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ निंजा द्वंद्व! वार से ठीक पहले ब्लॉक करो तो पैरी होगा, ब्लिंक से बचो। वार की तैयारी की चमक पर नज़र रखो",
"The two ninjas have met in a duel!":"दोनों निंजा द्वंद्व में भिड़ गईं!",
"⚔ Duel won! Our ninja prevails":"⚔ द्वंद्व जीता! हमारी निंजा भारी पड़ी",
