"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ ऑटो: खुद इलाकों में कूदती और काटती है। स्टिक / WASD से 1.5 सेकंड का विराम",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ हाथ से: दुश्मन पर टैप — डैश और वार, स्वाइप — घुमाकर वार, 🛡 — ब्लॉक",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ हाथ से: बायाँ क्लिक — कटाना, दायाँ क्लिक — ब्लॉक, Shift — ब्लिंक, Q — शुरिकेन, G — टेलीपोर्ट",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ निंजा: दुश्मन पर टैप — डैश और वार, दाईं ओर स्वाइप — प्रहार, ● — वार, 🛡 — ब्लॉक (सही समय = पैरी), ⇑ — ब्लिंक, ✦ — शुरिकेन, ◎ — टेलीपोर्ट, AUTO — अपने आप",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ निंजा: बायाँ क्लिक — कटाना (दबाए रखें — भारी वार), दायाँ क्लिक — ब्लॉक (सही समय = पैरी), Shift/Z — ब्लिंक, Q — शुरिकेन, G — क्रॉसहेयर तक टेलीपोर्ट, हवा में कूद — डबल जंप / दीवार-दौड़, {0} — AUTO",
