"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"रेडियो Portal Meteor: EDMITRY के 100+ ट्रैक सीधे गेम में — 📻 बटन (PC: key 5, [ ] — ट्रैक)। संगीत ज़रूरत पर स्ट्रीम होता है और गेम भारी नहीं करता; आवाज़ और ऑटोस्टार्ट सेटिंग्स में, साथ में \"Spotify पर सुनें\" लिंक।",
