"Radio":"रेडियो",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"रेडियो Portal Meteor चालू/बंद ([ ] — ट्रैक, Shift+[ ] — आवाज़)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 दाईं ओर — रेडियो Portal Meteor: लड़ाई के दौरान EDMITRY का संगीत।",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — रेडियो Portal Meteor: लड़ाई के दौरान EDMITRY का संगीत। [ ] — ट्रैक।",
"Radio Portal Meteor (EDMITRY): volume":"रेडियो Portal Meteor (EDMITRY): आवाज़",
"Radio: start by itself in battle":"रेडियो: लड़ाई में अपने आप चालू हो",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"रोबो-निंजा: कटाना वाली साइबॉर्ग। बैरक में \"शैडो प्रोटोकॉल\" शोध से खुलती है (मेक फ़ैक्टरी चाहिए)। खुद दुश्मन के क्षेत्रों में टेलीपोर्ट होती है, दुश्मनों को काट डालती है (खून नहीं — चिंगारियाँ), डैश, शुरिकेन, दुश्मन निंजा से द्वंद्व। उस पर हावी हों — AUTO मोड या मैनुअल नियंत्रण (फ़ोन पर अपने बटन)।",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"रेडियो Portal Meteor: EDMITRY के 103 ट्रैक सीधे गेम में। Key 5 (बदली जा सकती है), फ़ोन पर — ☰ → सेटिंग्स → ध्वनि। आवाज़ और \"लड़ाई में अपने आप चालू हो\" सेटिंग्स में; विस्फोटों और रेडियो की आवाज़ के नीचे संगीत धीमा हो जाता है।",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"नई भाषाएँ: उज़्बेक और ताजिक — पूर्ण; चीनी, स्पेनिश, पुर्तगाली — आंशिक। मेनू में \"नया मैच\" के पास नया भाषा चयन।",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"फ़ोन: \"आइकन छिपाएँ\" 👁 बचे बटनों को दाएँ किनारे पर सलीके से एक कॉलम में इकट्ठा करता है; पोर्ट्रेट में अब ओवरलैप नहीं होता; iPhone — गेम अब Safari के जेस्चर से नहीं टकराता, और \"शेयर → होम स्क्रीन में जोड़ें\" उसे पूरी स्क्रीन पर चलाता है।",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1 से: कोने में ☰ मेनू (विराम, फिर से, प्रशिक्षण, ग्राफ़िक्स), ऑटो-Dendy नहीं, फ़ोन पर ✋ एक्शन बटन। v7.8.1 और v7.8 \"🕘 गेम संस्करण\" मेनू में बने हैं।",
