"The bomber took off from the base — into the sky, it will come out over the target":"बमवर्षक बेस से उड़ा — आसमान में जा रहा है, लक्ष्य के ऊपर निकलेगा",
"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"यूनिट चुनो → “▶ काबू करें” या डबल टैप। ऊपर दाईं ओर मोड बटन: रणनीतिकार → कमांडर → शूटर।",
