"HELP":"मदद",
"GENERATOR":"जनरेटर",
"RELAY":"रिले",
"SABOTAGE":"तोड़फोड़",
"Living world: requests, hero quests, breakthrough ops":"जीवंत दुनिया: अनुरोध, हीरो क्वेस्ट, मोड़ के ऑपरेशन",
"Living world":"जीवंत दुनिया",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"अपने यूनिट मदद माँगते और इनाम देते हैं, हीरो क्वेस्ट देते हैं, रुका हुआ मोर्चा ऑपरेशन से टूटता है",
"A request":"अपनों का अनुरोध",
"Breakthrough":"मोड़ का क्षण",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"अपने यूनिट कभी-कभी मदद माँगते हैं: रेडियो पर आवाज़, “अनुरोध” कार्ड और ✋ निशान। कोई दस्ता घिर गया है — उसके पास के दुश्मनों को ख़त्म करो। इनाम: बेस से कैप्सूल में सैनिक, बग्गी से हथियार, गनर की सीट या कक्षा से कवर। न चाहो तो ✕ या बस अनदेखा करो।",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"अनुभवी टोही “उल्लू” क्वेस्ट देता है। Y — स्वीकार (N — इनकार)। ★ निशान तक जाओ, पहरेदारों को हटाओ और पायलट के पास 3 s खड़े रहो — वह तुम्हारे दस्ते में आ जाएगा।",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"मोर्चा रुक गया है — मुख्यालय मोड़ का ऑपरेशन देता है। Y — स्वीकार। आसपास दुश्मन के बिना रिले को 8 s थामो: दुश्मन का नक्शा 60 s दिखेगा। जनरेटर — दुश्मन के बुर्ज 2 मिनट शांत। स्ट्रैटेजिस्ट मोड में — “दस्ते को सौंपो”। दुश्मन भी ऐसा कर सकता है: ⚠ पर नज़र रखो।",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"अपने यूनिट मदद माँगते हैं: “अनुरोध” कार्ड और ✋ निशान। घिरे दस्ते के पास के दुश्मनों को ख़त्म करो — इनाम मिलेगा। ✕ — छोड़ो।",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"हीरो “उल्लू” क्वेस्ट देता है — “स्वीकार करें” टैप करो। ★ तक जाओ, पहरेदार हटाओ, पायलट के पास रुको।",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"मोर्चा रुक गया है — “स्वीकार करें” टैप करो और रिले को 8 s थामो: दुश्मन का नक्शा एक मिनट खुलेगा।",
"Pod redeploy from the base: {0} m — through the sky portal":"बेस से कैप्सूल द्वारा तैनाती: {0} m — आकाश द्वार से होकर",
"Pod away from the base! Hold on — exit over the target.":"कैप्सूल बेस से चल पड़ा! पकड़े रहो — लक्ष्य के ऊपर निकलेंगे।",
