"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"मुख्य युद्ध टैंक: तोप और मशीनगन। कंसोर्टियम का \"बुलडॉग\" ज़्यादा मज़बूत है, झुंड का \"स्पाइडर\" ज़्यादा तेज़।",
