"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"मुख्यालय के पास का साइलो: यहाँ से पॉड, सप्लाई क्रेट और बमवर्षक आकाश द्वार होकर लक्ष्य तक जाते हैं। इस पर निर्माण नहीं हो सकता।",
"Economy":"अर्थव्यवस्था",
"Key building":"मुख्य इमारत",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"कमज़ोर जगह — पिछला हिस्सा (इंजन): नुकसान ×{0}। तोप, 2 मशीनगन बुर्ज, रॉकेट पॉड; बहुत धीमे मुड़ता है — बगल से घेरो।",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"कमज़ोर जगह — पेट के नीचे चमकता कोर: नीचे से नुकसान ×{0}। विकृति किरण और क्षेत्र में पद-प्रहार; अवरोध लाँघ जाता है — दूरी रखो, झुंड में मत खड़े हो।",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"इसके खिलाफ़: हवाई बम और तोपखाना (×{0}), रॉकेट (×{1}), कालीन बमबारी; गोलियाँ लगभग बेअसर (×{2})।",
"Faction":"गुट",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"तेज़ मशीनें, ड्रोन झुंड, सुरंगें और पुनर्जनन। पैदल सेना हल्की पर तेज़; तोपें और रेल ज़्यादा मार करती हैं।",
