"Live in the Green anomalous zone, drawn to crystal veins. Neutral until touched or approached; dangerous to both sides. Fire and napalm ×1.6.":"\"हरे विसंगति क्षेत्र\" में रहते हैं, क्रिस्टल शिराओं की ओर खिंचते हैं। छेड़ने या पास जाने तक तटस्थ; दोनों पक्षों के लिए ख़तरनाक। आग और नैपाम ×1.6।",
