"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. आवाज़ के साथ स्क्रीन रिकॉर्डिंग चालू करें (PC पर — OBS, फ़ोन पर — माइक के साथ बिल्ट-इन स्क्रीन रिकॉर्डर) और यहाँ फ़ीडबैक मोड चालू करें।",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. खेलें और ज़ोर से सोचते जाएँ: क्या समझ नहीं आया, क्या खटका, क्या मज़ेदार लगा। कोने में वर्ज़न, समय और FPS दिखते हैं — इनसे रिकॉर्डिंग को नोट्स से मिलाया जाता है।",
"3. When something matters — take a note: PC ":"3. कुछ ज़रूरी लगे तो नोट लें: PC पर ",
" (press ":" (टेक्स्ट जोड़ने के लिए दोबारा दबाएँ ",
" again to add text), gamepad — hold View and press Start, phone — the ✎ button.":" ), गेमपैड पर — View दबाए रखें और Start दबाएँ, फ़ोन पर — ✎ बटन।",
"4. After playing: Download all and send the file to Claude together with the recording.":"4. खेलने के बाद: सब डाउनलोड करें और फ़ाइल रिकॉर्डिंग के साथ Claude को भेजें।",
