"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"ऊपर से देखें और पूरी सेना को कमान दें: अड्डा बनाएँ, दस्ते भेजें। सेना आपके बिना भी अपने आप लड़ती है।",
